def transform(g):
    h,w=len(g),len(g[0])
    cy=cx=None
    for r in range(h):
        for c in range(w):
            if g[r][c]==3: cy,cx=r,c
    out=[row[:] for row in g]
    path=[(0,0),(-1,0),(-2,0)]
    K=2
    while K<=60:
        for c in range(-(K-2)+1,K+1): path.append((-K,c))
        for r in range(-K+1,K+1): path.append((r,K))
        for c in range(K-1,-K-1,-1): path.append((K,c))
        for r in range(K-1,-K-1,-1): path.append((r,-K))
        path.append((-K-1,-K)); path.append((-K-2,-K))
        K+=2
    for dr,dc in path[1:]:
        r,c=cy+dr,cx+dc
        if 0<=r<h and 0<=c<w:
            if g[r][c]==2: break
            out[r][c]=3
    return out

